//! The record builder (PROV-S-004): caller-supplied facts of one committed
//! OCFL version become exactly one activity with its entities and agents.
//!
//! Rules, applied to the logical-state diff of the base state and the new state:
//!
//! - an **added** path is generated by the activity;
//! - a **changed** path (same path, new digest) is generated by the activity,
//!   derived from its previous state, and that previous state is used;
//! - a **moved** path (a `moves` entry, old path to new path) is generated by
//!   the activity, derived from the old path's base state, and that base
//!   state is used (a move is not a removal, so it is not invalidated);
//! - a **removed** path's base state is invalidated by the activity;
//! - an unchanged path produces no entity;
//! - generated entities are attributed to the installation agent, and the
//!   activity is associated with every agent;
//! - an agent the caller did not observe is stated as unrecorded;
//! - the activity ends at the version's `created` time.
//!
//! Paths under [`RECORD_PREFIX`] hold the records themselves; a record does
//! not describe them, since it cannot hold its own digest.

use std::collections::BTreeMap;

use crate::error::BuildError;
use crate::graph::assemble;
use crate::ids::{activity_id, entity_id, host_agent_id, unrecorded_agent_id};
use crate::model::{
    Activity, Agent, AgentKind, AgentRole, Derivation, Entity, HostFacts, ObjectVersion, Record,
};
use crate::profile::{to_json_ld, MAX_RECORD_BYTES};
use crate::scalar::{
    check_identifier, check_kind, check_label, check_path, check_version, InstallationId,
    Sha256Digest, Timestamp, MAX_MESSAGE_BYTES,
};

/// Logical-path prefix of the PROV-O records in an OCFL object (ADR 040
/// Decision 3); paths under it are left out of every record.
pub const RECORD_PREFIX: &str = "provenance/";

/// The OCFL version `user` block: a name and an optional address URI.
///
/// The name is never written into a record (no agent carries a display
/// name). An address of the form `urn:uuid:<uuid v4>` names the installation
/// agent when [`VersionFacts::installation`] is not given.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct OcflUser {
    /// The inventory's `user.name`.
    pub name: String,
    /// The inventory's `user.address`, if any.
    pub address: Option<String>,
}

/// Marks a record as reconstructed after the fact (backfill), with its own
/// recording time (`fsq:derivation: "reconstructed"`, `fsq:recordedAt`).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Reconstruction {
    /// When the reconstructed record is written, RFC 3339 UTC.
    pub recorded_at: String,
}

/// The facts of one committed OCFL version, as the caller observed them.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct VersionFacts {
    /// OCFL object identifier, for example `urn:uuid:<uuid>`.
    pub object_id: String,
    /// The committed version name as the inventory spells it, for example `v3`.
    pub version: String,
    /// The version the change was made on; `None` for the first version.
    pub base_version: Option<String>,
    /// The inventory `created` time of the version (RFC 3339 UTC); the activity's end.
    pub created: String,
    /// The inventory `user` block, if any.
    pub user: Option<OcflUser>,
    /// The inventory version message, if any; kept as `fsq:message`.
    pub message: Option<String>,
    /// Logical state of the base version: logical path to SHA-256 digest.
    pub base_state: BTreeMap<String, String>,
    /// Logical state of the new version: logical path to SHA-256 digest.
    pub new_state: BTreeMap<String, String>,
    /// Moves in this version: old logical path to new logical path.
    pub moves: BTreeMap<String, String>,
    /// The operation identifier (`fsq:operation`).
    pub operation_id: String,
    /// The operation kind (`fsq:kind`), for example `import`.
    pub kind: String,
    /// When the operation started (RFC 3339 UTC).
    pub started: String,
    /// The installation UUID (v4) if the caller observed it.
    pub installation: Option<String>,
    /// The FileSquid host if the caller observed it.
    pub host: Option<HostFacts>,
    /// Opaque journal entry identifiers of this commit.
    pub journal_entries: Vec<String>,
    /// Set when the record is reconstructed after the fact.
    pub reconstruction: Option<Reconstruction>,
}

/// Validated header facts of a version.
struct Header {
    activity_id: String,
    object_version: ObjectVersion,
    base_version: Option<String>,
    started: Timestamp,
    ended: Timestamp,
    recorded_at: Option<Timestamp>,
}

/// Validated base and new states, record paths left out.
struct States {
    base: BTreeMap<String, Sha256Digest>,
    new: BTreeMap<String, Sha256Digest>,
}

/// Build the one-activity record of `facts`.
///
/// # Errors
/// [`BuildError`] when a fact is malformed, a move does not match the
/// states, the start is after `created`, or the record would exceed 1 MiB.
pub fn build_record(facts: &VersionFacts) -> Result<Record, BuildError> {
    let header = check_header(facts)?;
    let states = check_states(facts, &header)?;
    check_moves(&facts.moves, &states)?;
    let agents = resolve_agents(facts)?;
    let installation_id = agents[0].id.clone();
    let mut agents = agents.to_vec();
    let entities = diff_entities(&header, &states, &facts.moves, &installation_id);
    let activity = new_activity(facts, &header, &entities, &agents);
    agents.sort_by(|a, b| a.id.cmp(&b.id));
    let record = assemble(activity, agents, entities.into_values().collect())
        .map_err(|reason| BuildError::Inconsistent { reason })?;
    if to_json_ld(&record).len() > MAX_RECORD_BYTES {
        return Err(BuildError::TooLarge);
    }
    Ok(record)
}

/// Return `Ok(())` when `ok`, else an invalid-fact error naming `field`.
fn require(ok: bool, field: &'static str) -> Result<(), BuildError> {
    ok.then_some(()).ok_or(BuildError::InvalidFact { field })
}

/// Parse a timestamp fact named `field`.
fn timestamp(text: &str, field: &'static str) -> Result<Timestamp, BuildError> {
    Timestamp::parse(text).map_err(|_| BuildError::InvalidFact { field })
}

/// Check the identifiers, times and message of `facts`.
fn check_header(facts: &VersionFacts) -> Result<Header, BuildError> {
    require(check_identifier(&facts.object_id), "object_id")?;
    require(check_version(&facts.version), "version")?;
    let base_ok = facts
        .base_version
        .as_deref()
        .is_none_or(|base| check_version(base) && base != facts.version);
    require(base_ok, "base_version")?;
    require(check_identifier(&facts.operation_id), "operation_id")?;
    require(check_kind(&facts.kind), "kind")?;
    let journal_ok = facts.journal_entries.iter().all(|id| check_identifier(id));
    require(journal_ok, "journal_entries")?;
    let message_ok = facts
        .message
        .as_ref()
        .is_none_or(|m| m.len() <= MAX_MESSAGE_BYTES);
    require(message_ok, "message")?;
    let started = timestamp(&facts.started, "started")?;
    let ended = timestamp(&facts.created, "created")?;
    if started.instant() > ended.instant() {
        return Err(BuildError::TimeOrder);
    }
    let recorded_at = facts
        .reconstruction
        .as_ref()
        .map(|r| timestamp(&r.recorded_at, "reconstruction"))
        .transpose()?;
    Ok(Header {
        activity_id: activity_id(&facts.operation_id, &facts.object_id, &facts.version),
        object_version: ObjectVersion {
            object_id: facts.object_id.clone(),
            version: facts.version.clone(),
        },
        base_version: facts.base_version.clone(),
        started,
        ended,
        recorded_at,
    })
}

/// Validate one state map and leave out the record paths.
fn check_state(
    state: &BTreeMap<String, String>,
    field: &'static str,
) -> Result<BTreeMap<String, Sha256Digest>, BuildError> {
    let mut checked = BTreeMap::new();
    for (path, digest) in state {
        require(check_path(path), field)?;
        let digest = Sha256Digest::parse(digest).map_err(|_| BuildError::InvalidFact { field })?;
        if !path.starts_with(RECORD_PREFIX) {
            checked.insert(path.clone(), digest);
        }
    }
    Ok(checked)
}

/// Validate both states; a first version has no base state.
fn check_states(facts: &VersionFacts, header: &Header) -> Result<States, BuildError> {
    let base = check_state(&facts.base_state, "base_state")?;
    let new = check_state(&facts.new_state, "new_state")?;
    let base_ok = header.base_version.is_some() || facts.base_state.is_empty();
    require(base_ok, "base_version")?;
    Ok(States { base, new })
}

/// Check that each move leaves a base path for a new path, and that no two
/// moves share a target. Chained moves (`A -> B`, `B -> C`) and swaps
/// (`A -> B`, `B -> A`) are allowed: a source may stay in the new state only
/// as the target of another move, and a target may be in the base state
/// only as the source of another move.
fn check_moves(moves: &BTreeMap<String, String>, states: &States) -> Result<(), BuildError> {
    let mut targets: Vec<&String> = moves.values().collect();
    targets.sort();
    let distinct = targets.windows(2).all(|pair| pair[0] != pair[1]);
    let consistent = moves
        .iter()
        .all(|(old, new)| move_fits(old, new, moves, &targets, states));
    (distinct && consistent)
        .then_some(())
        .ok_or(BuildError::InvalidMove)
}

/// Whether the move `old -> new` fits the states, given every move's
/// sources (`moves`) and its sorted `targets`.
fn move_fits(
    old: &String,
    new: &String,
    moves: &BTreeMap<String, String>,
    targets: &[&String],
    states: &States,
) -> bool {
    let old_vacated = !states.new.contains_key(old) || targets.binary_search(&old).is_ok();
    let new_free = !states.base.contains_key(new) || moves.contains_key(new);
    old != new
        && states.base.contains_key(old)
        && states.new.contains_key(new)
        && old_vacated
        && new_free
}

/// The installation agent and the host agent, recorded or unrecorded.
/// The installation agent comes first.
fn resolve_agents(facts: &VersionFacts) -> Result<[Agent; 2], BuildError> {
    let installation = installation_agent(facts)?;
    let host = match &facts.host {
        Some(host) => {
            let labels = [&host.product, &host.distribution, &host.version];
            require(labels.iter().all(|label| check_label(label)), "host")?;
            Agent {
                id: host_agent_id(host),
                kind: AgentKind::Host(host.clone()),
                acted_on_behalf_of: Some(installation.id.clone()),
            }
        }
        None => unrecorded(AgentRole::Host),
    };
    Ok([installation, host])
}

/// The unrecorded agent standing in for `role`.
fn unrecorded(role: AgentRole) -> Agent {
    Agent {
        id: unrecorded_agent_id(role),
        kind: AgentKind::Unrecorded(role),
        acted_on_behalf_of: None,
    }
}

/// The installation agent from the installation UUID, else from an OCFL
/// user address `urn:uuid:<uuid v4>`, else unrecorded. The user's name is
/// never used.
fn installation_agent(facts: &VersionFacts) -> Result<Agent, BuildError> {
    let from_user = facts
        .user
        .as_ref()
        .and_then(|user| user.address.as_deref())
        .and_then(|address| address.strip_prefix("urn:uuid:"))
        .and_then(|uuid| InstallationId::parse(uuid).ok());
    let observed = match &facts.installation {
        Some(text) => Some(
            InstallationId::parse(text).map_err(|_| BuildError::InvalidFact {
                field: "installation",
            })?,
        ),
        None => from_user,
    };
    Ok(match observed {
        Some(id) => Agent {
            id: id.urn(),
            kind: AgentKind::Installation(id),
            acted_on_behalf_of: None,
        },
        None => unrecorded(AgentRole::Installation),
    })
}

/// A new state of `path` generated by the activity.
fn generated(header: &Header, path: &str, digest: &Sha256Digest, installation: &str) -> Entity {
    let object = &header.object_version;
    Entity {
        id: entity_id(&object.object_id, &object.version, path),
        object_id: object.object_id.clone(),
        version: object.version.clone(),
        path: path.to_string(),
        sha256: digest.clone(),
        generated_by: Some(header.activity_id.clone()),
        derived_from: Vec::new(),
        invalidated_by: None,
        attributed_to: vec![installation.to_string()],
    }
}

/// The base state of `path` (only called when a base version exists).
fn base_entity(header: &Header, base_version: &str, path: &str, digest: &Sha256Digest) -> Entity {
    let object_id = &header.object_version.object_id;
    Entity {
        id: entity_id(object_id, base_version, path),
        object_id: object_id.clone(),
        version: base_version.to_string(),
        path: path.to_string(),
        sha256: digest.clone(),
        generated_by: None,
        derived_from: Vec::new(),
        invalidated_by: None,
        attributed_to: Vec::new(),
    }
}

/// Every entity of the diff, keyed by identifier.
fn diff_entities(
    header: &Header,
    states: &States,
    moves: &BTreeMap<String, String>,
    installation: &str,
) -> BTreeMap<String, Entity> {
    let mut entities = BTreeMap::new();
    let sources: BTreeMap<&String, &String> = moves.iter().map(|(old, new)| (new, old)).collect();
    let base_version = header.base_version.as_deref().unwrap_or_default();
    for (path, digest) in &states.new {
        let previous = sources.get(path).copied().unwrap_or(path);
        let before = states.base.get(previous);
        if before == Some(digest) && previous == path {
            continue;
        }
        let mut entity = generated(header, path, digest, installation);
        if let Some(before) = before {
            let source = base_entity(header, base_version, previous, before);
            entity.derived_from.push(source.id.clone());
            entities.insert(source.id.clone(), source);
        }
        entities.insert(entity.id.clone(), entity);
    }
    let moved: Vec<&String> = moves.keys().collect();
    for (path, digest) in states
        .base
        .iter()
        .filter(|(p, _)| !states.new.contains_key(*p))
    {
        if moved.contains(&path) {
            continue;
        }
        let mut removed = base_entity(header, base_version, path, digest);
        removed.invalidated_by = Some(header.activity_id.clone());
        entities.insert(removed.id.clone(), removed);
    }
    entities
}

/// The activity: used inputs are every base state a generated state derives from.
fn new_activity(
    facts: &VersionFacts,
    header: &Header,
    entities: &BTreeMap<String, Entity>,
    agents: &[Agent],
) -> Activity {
    let used = entities
        .values()
        .flat_map(|entity| entity.derived_from.iter().cloned())
        .collect();
    Activity {
        id: header.activity_id.clone(),
        operation: facts.operation_id.clone(),
        kind: facts.kind.clone(),
        object_version: header.object_version.clone(),
        started_at: header.started.clone(),
        ended_at: header.ended.clone(),
        journal_entries: facts.journal_entries.clone(),
        message: facts.message.clone(),
        used,
        associated_with: agents.iter().map(|agent| agent.id.clone()).collect(),
        derivation: header
            .recorded_at
            .as_ref()
            .map(|_| Derivation::Reconstructed),
        recorded_at: header.recorded_at.clone(),
    }
}
